function lockControls(){const previous=Array.from(document.querySelectorAll('button,select,input')).map(node=>[node,node.disabled]);for(const [node] of previous)node.disabled=true;return ()=>{for(const [node,disabled] of previous)if(node.isConnected)node.disabled=disabled;};}
