    if(!hasUnit(parsed.up_id))throw Error('UP du dossier inconnue.');
    const choices=parsed.up_id==='biscuiterie'?window.P2I_BP_V108_REFERENCES.variants:parsed.up_id==='nettoyage'?window.P2I_BP_V108_REFERENCES.nettoyage:null;
    if(parsed.configuration_id!==null&&(typeof parsed.configuration_id!=='string'||!/^[a-z0-9_-]{1,100}$/i.test(parsed.configuration_id)||choices&&!Object.prototype.hasOwnProperty.call(choices,parsed.configuration_id)))throw Error('Variante du dossier inconnue.');
    contextAPI.detach();contextState={mode:'reference'};id=parsed.up_id;config=parsed.configuration_id;override=null;actionMessage='Référence du dossier importée et recalculée avec les données disponibles. Aucun résultat mis en cache ni identifiant de compte du fichier n’est utilisé.';updateURL();render();return;
