   id=entry.up_id;config=entry.configuration_id;override=entry;contextState={...contextState,modifie:true};actionMessage='Paramètres importés et recalculés. Ils restent des hypothèses non vérifiées.';
   if(!contextAPI.snapshot())updateURL();render();document.getElementById('p2i-r2').scrollIntoView();
