function updateURL(){const p=new URLSearchParams(location.search);p.set('unit_id',id);p.set('unit',registry[id].nom);p.set('filiere',registry[id].filiereNom||'');for(const key of ['up_id','id','simulation_id','equipment_plan_id','capacity_value','capacity_unit','capacity_label','nom'])p.delete(key);if(config)p.set('configuration_id',config);else p.delete('configuration_id');history.replaceState(null,'',location.pathname+'?'+p);}
async function boot(){
 const sim=params.get('simulation_id')||(!params.get('unit_id')&&!params.get('up_id')&&params.get('id')&&!hasUnit(params.get('id'))?params.get('id'):null);
 if(!sim&&!hasUnit(id)&&/^\d+$/.test(id)){
  try{id=window.P2I_BP_V108_CONTEXTE.resolveUnit({unit_id:id,unit:params.get('unit')||params.get('nom')||params.get('unit_name')},registry);if(!config&&id==='biscuiterie')config='crackers';const q=new URLSearchParams(location.search);q.set('unit_id',id);q.delete('id');q.delete('up_id');history.replaceState(null,'',location.pathname+'?'+q);}
  catch(error){failure('Identifiant numérique ancien : le nom exact de l’UP est nécessaire pour retrouver sa référence.');return;}
 }
 if(sim){
  document.getElementById('app').innerHTML='<main class="restore-error"><h1>Chargement de votre simulation P2I…</h1><p>Vérification de la session et du dossier propriétaire.</p></main>';
  try{
   if(location.protocol==='file:')throw Error('Ouvrez ce fichier depuis le site P2I pour réutiliser votre session connectée.');
   const result=await contextAPI.restore(sim);id=result.up_id;config=result.configuration_id;override=result.entrees;contextState={mode:'restaure',...result};
   const q=new URLSearchParams(location.search);q.set('unit_id',id);q.set('unit',registry[id].nom);q.set('filiere',registry[id].filiereNom||'');if(config)q.set('configuration_id',config);else q.delete('configuration_id');q.delete('up_id');q.delete('id');history.replaceState(null,'',location.pathname+'?'+q);
  }catch(error){failure(error.message);return;}
 }
 render();
}
